tool_calls:
cd /home/eval/pkgs; mkdir -p bin build; cat > bin/order <<'EOF'
#!/bin/bash
# Deterministic topological build order (smallest ready package first, byte order).
export LC_ALL=C
if [ $# -ne 1 ] || [ ! -r "$1" ]; then
  echo "usage: order FILE" >&2; exit 2
fi
awk '
function addpkg(p) { if (!(p in seen)) { seen[p]=1; names[++n]=p } }
{
  sub(/\r$/, "")
  sub(/#.*/, "")
  if ($0 ~ /^[ \t]*$/) next
  c = index($0, ":")
  if (c == 0) { m = split($0, t, /[ \t]+/); for (i=1;i<=m;i++) if (t[i]!="") addpkg(t[i]); next }
  lhs = substr($0, 1, c-1); rhs = substr($0, c+1)
  gsub(/^[ \t]+|[ \t]+$/, "", lhs)
  if (lhs != "") addpkg(lhs)
  m = split(rhs, t, /[ \t]+/)
  for (i=1;i<=m;i++) {
    d = t[i]; if (d == "") continue
    addpkg(d)
    if (lhs == "") continue
    if (!((lhs SUBSEP d) in edge)) {
      edge[lhs SUBSEP d]=1
      indeg[lhs]++
      nr[d]++; rdep[d, nr[d]] = lhs
    }
  }
}
END {
  # ready set as a plain array; pick min each time
  for (i=1;i<=n;i++) { p=names[i]; if (!(indeg[p]+0)) ready[p]=1 }
  emitted = 0
  while (1) {
    best = ""; found = 0
    for (p in ready) if (!found || p < best) { best = p; found = 1 }
    if (!found) break
    delete ready[best]; done[best]=1; emitted++
    print best
    for (j=1;j<=nr[best]+0;j++) { q = rdep[best, j]; if (--indeg[q] == 0) ready[q]=1 }
  }
  if (emitted < n) {
    k = 0
    for (i=1;i<=n;i++) if (!(names[i] in done)) rem[++k] = names[i]
    # insertion sort (byte order under LC_ALL=C)
    for (i=2;i<=k;i++) { v=rem[i]; j=i-1; while (j>0 && rem[j] > v) { rem[j+1]=rem[j]; j-- } rem[j+1]=v }
    s = "cycle:"
    for (i=1;i<=k;i++) s = s " " rem[i]
    print s > "/dev/stderr"
    exit 1
  }
}' "$1"
EOF
chmod +x bin/order
bin/order deps.txt > build/order.txt
bin/order deps-big.txt > build/big-order.txt
bin/order deps-cycle.txt > build/cycle-order.txt 2> build/cycle.txt; echo $? > build/cycle.rc
for f in build/*; do echo "== $f"; cat $f; done

